from typing import Dict, List


def parse_script(text: str) -> Dict[str, List[dict]]:
    lines = text.splitlines()
    sections = {}
    current_id = None
    current_lines = []

    for line in lines:
        line = line.strip()
        if not line:
            continue
        if line.startswith('[') and line.endswith(']'):
            if current_id is not None:
                sections[current_id] = current_lines
            current_id = line[1:-1].strip()
            current_lines = []
        else:
            if current_id is None:
                continue
            current_lines.append(line)
    if current_id is not None:
        sections[current_id] = current_lines

    nodes = []
    edges = []

    for node_id, content_lines in sections.items():
        # Determine if this is a choice node
        is_choice = all(re.match(r'^\d+\.\s*', ln) for ln in content_lines)

        if is_choice:
            nodes.append({"id": node_id, "text": "", "speaker": "", "type": "choice"})
            for ln in content_lines:
                # Strip leading number
                ln = re.sub(r'^\d+\.\s*', '', ln)
                if '->' in ln:
                    left, right = ln.rsplit('->', 1)
                    choice_text = left.strip()
                    target = right.strip()
                else:
                    choice_text = ln.strip()
                    target = ''
                edges.append({"from": node_id, "to": target, "text": choice_text})
        else:
            # treat first line as dialogue line
            if not content_lines:
                nodes.append({"id": node_id, "text": "", "speaker": "", "type": "line"})
                continue
            ln = content_lines[0]
            speaker = ""
            text_part = ln
            if ':' in ln:
                speaker, text_part = ln.split(':', 1)
                speaker = speaker.strip()
                text_part = text_part.strip()
            target = ""
            if '->' in text_part:
                left, right = text_part.rsplit('->', 1)
                text_part = left.strip()
                target = right.strip()
            nodes.append({"id": node_id, "text": text_part, "speaker": speaker, "type": "line"})
            if target:
                edges.append({"from": node_id, "to": target, "text": ""})

    # Add implicit End node if referenced
    node_ids = {n['id'] for n in nodes}
    targets = {e['to'] for e in edges if e['to']}
    for tgt in targets:
        if tgt not in node_ids:
            nodes.append({"id": tgt, "text": "", "speaker": "", "type": "line"})
            node_ids.add(tgt)

    return {"nodes": nodes, "edges": edges}


def graph_to_dot(graph: Dict[str, List[dict]]) -> str:
    lines = ["digraph dialogue {"]
    for node in graph['nodes']:
        label = node['id']
        if node['type'] == 'line':
            if node['speaker']:
                label = f"{node['id']}\\n{node['speaker']}: {node['text']}"
            else:
                label = f"{node['id']}\\n{node['text']}"
        lines.append(f"  \"{node['id']}\" [label=\"{label}\"];" )
    for edge in graph['edges']:
        if edge['text']:
            lines.append(f"  \"{edge['from']}\" -> \"{edge['to']}\" [label=\"{edge['text']}\"];" )
        else:
            lines.append(f"  \"{edge['from']}\" -> \"{edge['to']}\";" )
    lines.append("}")
    return "\n".join(lines)


if __name__ == '__main__':
    with open('/app/script.txt', 'r', encoding='utf-8') as f:
        text = f.read()
    graph = parse_script(text)
    with open('/app/dialogue.json', 'w', encoding='utf-8') as f:
        json.dump(graph, f, indent=2)
    dot = graph_to_dot(graph)
    with open('/app/dialogue.dot', 'w', encoding='utf-8') as f:
        f.write(dot)
